import { describe, expect, it, vi } from "vitest";
import { parseUpdateMode, runUpdateCommands } from "./update.js";
describe("runUpdateCommands", () => {
    const commands = [
        "claude plugin marketplace update bitfab",
        "claude plugin update bitfab@bitfab --scope user",
        "claude plugin update bitfab@bitfab --scope project",
    ];
    it("returns no failures when every command succeeds", () => {
        const run = vi.fn();
        expect(runUpdateCommands(commands, run)).toEqual([]);
        expect(run).toHaveBeenCalledTimes(3);
    });
    it("still updates the remaining scopes after one fails", () => {
        const attempted = [];
        const failed = runUpdateCommands(commands, (command) => {
            attempted.push(command);
            if (command.endsWith("--scope user")) {
                throw new Error("not installed at scope user");
            }
        });
        expect(attempted).toEqual(commands);
        expect(failed).toEqual(["claude plugin update bitfab@bitfab --scope user"]);
    });
    it("reports every failed command", () => {
        const failed = runUpdateCommands(commands, () => {
            throw new Error("offline");
        });
        expect(failed).toEqual(commands);
    });
});
describe("parseUpdateMode", () => {
    it('defaults to "all" for undefined', () => {
        expect(parseUpdateMode(undefined)).toBe("all");
    });
    it('accepts "all"', () => {
        expect(parseUpdateMode("all")).toBe("all");
    });
    it('accepts "plugin"', () => {
        expect(parseUpdateMode("plugin")).toBe("plugin");
    });
    it('accepts "sdk"', () => {
        expect(parseUpdateMode("sdk")).toBe("sdk");
    });
    it("throws on unknown modes", () => {
        expect(() => parseUpdateMode("everything")).toThrow(/Unknown update mode/);
    });
    // Help is honored anywhere in argv, not just when the mode slot is the flag,
    // so `update plugin -h` shows help instead of running an update.
    it.each([
        [["node", "update.js", "-h"]],
        [["node", "update.js", "--help"]],
        [["node", "update.js", "plugin", "-h"]],
        [["node", "update.js", "sdk", "--help"]],
    ])("prints help and exits 0 for argv %s", (argv) => {
        const origArgv = process.argv;
        process.argv = argv;
        // Throw from the mock so execution stops at the exit call, like a real exit.
        const mockExit = vi.spyOn(process, "exit").mockImplementation(() => {
            throw new Error("process.exit");
        });
        const mockLog = vi.spyOn(console, "log").mockImplementation(() => { });
        expect(() => parseUpdateMode(argv[2])).toThrow("process.exit");
        expect(mockExit).toHaveBeenCalledWith(0);
        expect(mockLog).toHaveBeenCalledWith(expect.stringContaining("Usage: update [mode]"));
        process.argv = origArgv;
        mockExit.mockRestore();
        mockLog.mockRestore();
    });
});
